const incomingItems = $input.all();
const historyRows = incomingItems
  .map(item => item.json)
  .filter(row => row && !row.error && (row.content || row.created_at || row.timestamp || row.role));

if (historyRows.length === 0) {
  return { json: { formatted_history: [] } };
}

const sorted = historyRows.sort((a, b) => {
  const ta = new Date(a.created_at || a.timestamp || 0).getTime();
  const tb = new Date(b.created_at || b.timestamp || 0).getTime();
  return ta - tb;
});

const formattedHistory = sorted
  .slice(-20)
  .map(msg => ({
    role: msg.role === "assistant" ? "assistant" : "user",
    content: String(msg.content || "")
  }))
  .filter(msg => msg.content.trim() !== "");

return {
  json: {
    formatted_history: formattedHistory
  }
};

const rawUserMsg = String($('Normalize Incoming Message').first().json.userMessage || '');
const userMsg = rawUserMsg.toLowerCase();

// ─── Intent Detection ──────────────────────────────────────────────────────
const intents = {
  price: /harga|biaya|bayar|berapa|paket|membership|member|promo|diskon|trial|pricelist|price list|list harga|tarif|cicil|worth|sebanding|investasi|murah|mahal|kemahalan/.test(userMsg),

  class: /kelas|jadwal|program|class|olahraga|latihan|yoga|strength|pilates|fitdance|boxing|trampoline|aerobic|body combat|power step|cardio|hiit|tabata|abs|core|toning/.test(userMsg),

  coach: /coach|pelatih|trainer|instruktur|pengajar|guru|komunitas|support|siapa yang ngajar|siapa coachnya/.test(userMsg),

  location: /lokasi|alamat|dimana|di mana|maps|google map|parkir|fasilitas|tempat|kepanjen|malang|akses|rute|jalan/.test(userMsg),

  challenge: /21 hari|21 days|challenge|meal plan|nutrisi|diet|meal replacement|program diet|program 21/.test(userMsg),

  goals: /target|goals|turun|naik|berat|langsing|fit|sehat|percaya diri|gemuk|kurus|ideal|diet|bentuk badan|perut|pinggang|obesitas|badan|tubuh|transformasi|program turun/.test(userMsg),

  registration: /daftar|daftarnya|join|gabung|pendaftaran|booking|form|formulir|isi form|cara daftar|gimana daftar|bagaimana daftar|bisa daftar|daftar di sini|daftar disini|minta form|mau coba|pengen coba|cobain dulu|trial gratis|coba dulu/.test(userMsg),

  admin: /admin|nomor admin|kontak admin|wa admin|whatsapp admin|cs admin|hubungi admin|contact|nomornya|nomor wa/.test(userMsg),

  social: /instagram|ig\b|sosmed|sosial media|social media|portfolio|portofolio|gambaran|keseruan|transformasi|foto|ulasan|testimoni|before after|sebelum sesudah|hasilnya|bukti|review/.test(userMsg),

  objection: /mahal|kemahalan|mahal banget|mahal amat|kok mahal|terlalu mahal|harga tinggi|harga mahal|bisa lebih murah|ada yang lebih murah|kurang terjangkau|worth it|worth ga|sebanding ga|sepadan/.test(userMsg),

  about: /stepup itu|tentang stepup|apa itu stepup|cerita dong|ceritain|gimana stepup|profil|sejarah|gym perempuan|gym wanita|ladies gym|khusus wanita|khusus perempuan|bedanya sama gym lain|bedanya apa dengan/.test(userMsg),

  event: /event|acara|lomba|kompetisi|special event|open class|free class|kelas gratis|kelas special/.test(userMsg),
};

// ─── Category Mapping ──────────────────────────────────────────────────────
const categoryMap = {
  price:        ['harga_pembayaran'],
  class:        ['kelas_program'],
  coach:        ['coach_community'],
  location:     ['lokasi_fasilitas'],
  challenge:    ['challenge_21_days', 'harga_pembayaran'],
  goals:        ['goals_transformasi', 'target_member'],
  registration: ['pendaftaran'],
  admin:        ['admin'],
  social:       ['tentang_stepup'],
  objection:    ['harga_pembayaran', 'tentang_stepup'],
  about:        ['tentang_stepup', 'faq_umum'],
  event:        ['tentang_stepup', 'faq_umum'],
};

const defaultCategories = new Set(['tentang_stepup', 'faq_umum']);
const preferredCategories = new Set(defaultCategories);
for (const [intent, active] of Object.entries(intents)) {
  if (active && categoryMap[intent]) categoryMap[intent].forEach(c => preferredCategories.add(c));
}

// ─── Score KB Rows ─────────────────────────────────────────────────────────
const allKb = $('Fetch Knowledge Base').all()
  .map(d => d.json)
  .filter(row => row && (row.description || row.content || row.category || row.intent_name));

const stopWords = new Set(['yang','dan','ini','itu','bisa','mau','ada','untuk','dengan','apa','kak','ya','ga','gak','tidak','mau','kak','kak']);

const keywordParts = [...new Set(
  userMsg
    .replace(/[^a-z0-9\s]/gi, ' ')
    .split(/\s+/)
    .map(s => s.trim())
    .filter(s => s.length >= 3 && !stopWords.has(s))
)];

function scoreRow(row) {
  const cat = String(row.category || '').toLowerCase();
  const intent = String(row.intent_name || '').toLowerCase();
  const text = [row.intent_name, row.description, row.content, row.title, row.category]
    .map(v => String(v || '').toLowerCase())
    .join(' ');

  let score = 0;
  if (preferredCategories.has(cat)) score += 8;
  if (defaultCategories.has(cat)) score += 2;

  for (const kw of keywordParts) {
    if (intent.includes(kw)) score += 6;
    if (cat.includes(kw)) score += 4;
    if (text.includes(kw)) score += 2;
  }

  if (intents.admin     && cat === 'admin')                                           score += 20;
  if (intents.location  && cat === 'lokasi_fasilitas')                                score += 20;
  if (intents.about     && cat === 'tentang_stepup')                                  score += 18;
  if (intents.price     && cat === 'harga_pembayaran')                                score += 15;
  if (intents.objection && cat === 'harga_pembayaran')                                score += 15;
  if (intents.registration && cat === 'pendaftaran')                                  score += 15;
  if (intents.challenge && cat === 'challenge_21_days')                               score += 15;
  if (intents.coach     && cat === 'coach_community')                                 score += 15;
  if (intents.social    && cat === 'tentang_stepup')                                  score += 15;
  if (intents.objection && cat === 'tentang_stepup')                                  score += 10;
  if (intents.about     && cat === 'faq_umum')                                        score += 10;
  if (intents.goals     && (cat === 'goals_transformasi' || cat === 'target_member')) score += 12;
  if (intents.class     && cat === 'kelas_program')                                   score += 12;

  return score;
}

const scoredKb = allKb
  .map(row => ({ row, score: scoreRow(row) }))
  .filter(entry => entry.score > 0)
  .sort((a, b) => b.score - a.score || Number(a.row.id || 0) - Number(b.row.id || 0));

const fallbackKb = allKb
  .filter(row => defaultCategories.has(String(row.category || '').toLowerCase()))
  .slice(0, 8)
  .map(row => ({ row, score: 1 }));

const maxKb = (intents.admin || intents.about) ? 20 : 16;
const finalKb = (scoredKb.length ? scoredKb : fallbackKb)
  .slice(0, maxKb)
  .map(entry => entry.row);

const kbItems = finalKb.map(row => ({ json: { ...row, _source: 'kb' } }));

// ─── Sheet Data ────────────────────────────────────────────────────────────
const sheetItems = [];

// Filter jadwal by hari jika disebutkan
const dayList = ['senin','selasa','rabu','kamis','jumat',"jum'at",'sabtu','minggu'];
const mentionedDay = dayList.find(d => userMsg.includes(d)) || null;

// Harga & Promo
if (intents.price || intents.challenge || intents.objection || intents.registration) {
  const hargaRows = $('Fetch Sheet Harga').all().map(d => d.json).filter(r => {
    if (!r || !r.nama_paket) return false;
    const s = String(r.status || '').toLowerCase();
    return !s || s === 'aktif' || s === 'active';
  });
  for (const row of hargaRows) {
    sheetItems.push({
      json: {
        _source: 'sheet_harga',
        category: 'harga_pembayaran',
        content: [
          `Nama Paket: ${row.nama_paket}`,
          row.kategori        ? `Kategori: ${row.kategori}` : '',
          row.harga           ? `Harga: ${row.harga}` : '',
          row.durasi          ? `Durasi: ${row.durasi}` : '',
          row.fasilitas_utama ? `Fasilitas: ${row.fasilitas_utama}` : '',
          row.ketentuan       ? `Ketentuan: ${row.ketentuan}` : '',
          row.cocok_untuk     ? `Cocok Untuk: ${row.cocok_untuk}` : '',
        ].filter(Boolean).join(' | '),
      }
    });
  }

  const promoRows = $('Fetch Sheet Promo').all().map(d => d.json).filter(r =>
    r && r.nama_promo && String(r.status || '').toLowerCase() === 'active'
  );
  for (const row of promoRows) {
    sheetItems.push({
      json: {
        _source: 'sheet_promo',
        category: 'harga_pembayaran',
        content: [
          `Promo: ${row.nama_promo}`,
          row.diskon ? `Diskon: ${row.diskon}` : '',
          row.harga  ? `Harga Promo: ${row.harga}` : '',
          row.syarat ? `Syarat: ${row.syarat}` : '',
        ].filter(Boolean).join(' | '),
      }
    });
  }
}

// Jadwal (filter by hari jika ada)
if (intents.class) {
  let rows = $('Fetch Sheet Jadwal').all().map(d => d.json).filter(r => r && (r.nama_kelas || r.kelas));
  if (mentionedDay) {
    const filtered = rows.filter(r => String(r.hari || '').toLowerCase().includes(mentionedDay));
    if (filtered.length > 0) rows = filtered;
  }
  for (const row of rows) {
    sheetItems.push({
      json: {
        _source: 'sheet_jadwal',
        category: 'kelas_program',
        content: [
          `Kelas: ${row.nama_kelas || row.kelas || ''}`,
          row.hari  ? `Hari: ${row.hari}` : '',
          row.jam   ? `Jam: ${row.jam}` : '',
          row.coach ? `Coach: ${row.coach}` : '',
        ].filter(Boolean).join(' | ')
      }
    });
  }
}

// Coach
if (intents.coach) {
  const rows = $('Fetch Sheet Coach').all().map(d => d.json).filter(r => r && r.nama_coach);
  for (const row of rows) {
    sheetItems.push({
      json: {
        _source: 'sheet_coach',
        category: 'coach_community',
        content: [
          `Coach: ${row.nama_coach}`,
          row.specialist    ? `Specialist: ${row.specialist}` : '',
          row.hari_mengajar ? `Mengajar: ${row.hari_mengajar}` : '',
          row.bio           ? `Bio: ${row.bio}` : '',
        ].filter(Boolean).join(' | ')
      }
    });
  }
}

// Event & Challenge
if (intents.challenge || intents.event || intents.goals) {
  const rows = $('Fetch Sheet Event').all().map(d => d.json).filter(r => {
    if (!r) return false;
    const s = String(r.status || '').toLowerCase();
    return !s || s === 'aktif' || s === 'active';
  });
  for (const row of rows) {
    sheetItems.push({
      json: {
        _source: 'sheet_event',
        category: 'challenge_21_days',
        content: [
          (row.nama_event || row.nama_program) ? `Event: ${row.nama_event || row.nama_program}` : '',
          row.deskripsi ? `Deskripsi: ${row.deskripsi}` : '',
          row.harga     ? `Harga: ${row.harga}` : '',
          row.durasi    ? `Durasi: ${row.durasi}` : '',
          row.fasilitas ? `Fasilitas: ${row.fasilitas}` : '',
        ].filter(Boolean).join(' | ')
      }
    });
  }
}

return [...sheetItems, ...kbItems];

function safeGet(nodeName) {
  try {
    return $(nodeName).all().map(d => d.json).filter(row => row && !row.error && Object.keys(row).length > 0);
  } catch (e) {
    return [];
  }
}

function safeFirst(nodeName) {
  try {
    return $(nodeName).first().json || {};
  } catch (e) {
    return {};
  }
}

const incoming = safeFirst('Normalize Incoming Message');
const rawUserMsg = String(incoming.userMessage || '');
const userMsg = rawUserMsg.toLowerCase();

const nowJkt = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Jakarta' }));
const dayNames = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
const currentDayName = dayNames[nowJkt.getDay()];
const currentHour = nowJkt.getHours();
const currentTimeStr = nowJkt.toTimeString().slice(0, 5) + ' WIB';
const greetingTime = currentHour < 11 ? 'pagi' : currentHour < 15 ? 'siang' : currentHour < 18 ? 'sore' : 'malam';

const resolvedUserMsg = userMsg
  .replace(/\bhari ini\b/g, currentDayName.toLowerCase())
  .replace(/\bsekarang\b(?=.*jadwal)/g, currentDayName.toLowerCase())
  .replace(/\bjum'at\b/g, 'jumat');

const mentionsToday = /hari ini|sekarang|today/.test(userMsg);

function isActive(row) {
  const s = String(row.status || row.Status || '').toLowerCase().trim();
  return !s || s === 'aktif' || s === 'active';
}

function rupiahNumber(v) {
  const n = Number(String(v || '').replace(/\D/g, ''));
  return Number.isFinite(n) && n > 0 ? n : null;
}

function rupiahFormat(n) {
  return 'Rp' + Number(n).toLocaleString('id-ID');
}

function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function splitMultiValue(value) {
  return String(value || '')
    .split(/[,/|;]/)
    .map(v => normalizeText(v))
    .filter(Boolean);
}

function compactRow(row, keys) {
  return keys.map(k => row[k] ? `${k}: ${row[k]}` : '').filter(Boolean).join(' | ');
}

function formatRows(rows, keys) {
  return rows
    .filter(isActive)
    .map(r => compactRow(r, keys))
    .filter(Boolean)
    .join('\n');
}

function unique(rows, key) {
  return [...new Set(rows.map(r => String(r[key] || '').trim()).filter(Boolean))];
}

function pickClassName(row) {
  return String(row.kelas || row.nama_kelas || '').trim();
}

const allHarga = safeGet('Fetch Sheet Harga').filter(isActive);
const allJadwal = safeGet('Fetch Sheet Jadwal')
  .filter(isActive)
  .map(row => ({
    ...row,
    kelas: pickClassName(row),
    hari: String(row.hari || '').trim(),
    jam: String(row.jam || '').trim(),
    coach: String(row.coach || '').trim()
  }))
  .filter(row => row.kelas);
const allCoachRaw = safeGet('Fetch Sheet Coach').filter(isActive);

const resolveClassDetail = safeFirst('Resolve Class Detail');
