function humanClean(text) {
  return String(text || '')
    .replace(/\[INTENT:JOIN\]/g, ' [INTENT:JOIN] ')
    .replace(/^#{1,6}\s*/gm, '')
    .replace(/\*\*(.*?)\*\*/g, '$1')
    .replace(/\*(.*?)\*/g, '$1')
    .replace(/__(.*?)__/g, '$1')
    .replace(/_(.*?)_/g, '$1')
    .replace(/`/g, '')
    .replace(/[ \t]+$/gm, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function classifyJoinIntent(userText, modelText) {
  const msg = String(userText || '').toLowerCase().trim();
  const modelMarkedJoin = String(modelText || '').includes('[INTENT:JOIN]');
  const registrationPhrases = /(cara daftar|gimana daftar|bagaimana daftar|daftarnya gimana|daftarnya bagaimana|bisa daftar|daftar di sini|daftar disini|langsung daftar|minta form|minta formulir|kirim form|kirim formulir|isi form|isi formulir|mau daftar|ingin daftar|pengen daftar|mau join|ingin join|pengen join|booking sekarang)/i;
  const asksInfo = /(apa saja|apa aja|harga|berapa|biaya|promo|trial|kelas|program|jadwal|jam|hari|kapan|lokasi|alamat|dimana|fasilitas|coach|special class)/i.test(msg) && !registrationPhrases.test(msg);
  const explicitJoinOnly =
    /(saya|aku|sy|aq)\s*(mau|ingin|pengen)\s*(daftar|join|booking|isi form)\b/i.test(msg) ||
    /^(daftar|join|booking|isi form|mau daftar|mau join)\b/i.test(msg) ||
    /(boleh|bisa)\s*(kirim|isi)\s*(form|formulir)/i.test(msg) ||
    registrationPhrases.test(msg);

  return (modelMarkedJoin || explicitJoinOnly) && explicitJoinOnly && !asksInfo;
}

function formatCoachReply(rows) {
  if (!Array.isArray(rows) || rows.length === 0) {
    return 'Mohon maaf kak, informasi coach untuk kelas tersebut belum tersedia di data kami ya.';
  }

  if (rows.length === 1) {
    const row = rows[0];
    const parts = [`Coach untuk kelas itu adalah ${row.nama_coach} ya kak`];
    if (row.specialist) parts.push(`Specialist: ${row.specialist}`);
    if (row.hari_mengajar) parts.push(`Hari mengajar: ${row.hari_mengajar}`);
    return parts.join('\n');
  }

  const lines = ['Untuk kelas ini, coach yang bisa mendampingi kakak adalah:'];
  rows.forEach(row => {
    const detail = [
      row.nama_coach || '',
      row.specialist ? `(${row.specialist})` : ''
    ].filter(Boolean).join(' ');
    if (detail) lines.push(`- ${detail}`);
  });

  return lines.join('\n');
}

function startsWithGreeting(text) {
  return /^(waalaikumsalam|assalamualaikum|selamat pagi|selamat siang|selamat sore|selamat malam|pagi kak|siang kak|sore kak|malam kak|hai kak|halo kak|hello kak|hi kak|hai|halo|hello|hi)\b/i.test(String(text || '').trim());
}

function getGreeting(text) {
  if (/assalamualaikum/i.test(text)) return 'Waalaikumsalam kak, ';
  if (/selamat pagi|pagi/i.test(text)) return 'Pagi kak, ';
  if (/selamat siang|siang/i.test(text)) return 'Siang kak, ';
  if (/selamat sore|sore/i.test(text)) return 'Sore kak, ';
  if (/selamat malam|malam/i.test(text)) return 'Malam kak, ';
  if (/halo|hallo|hello|hi|hey|hai|hei/i.test(text)) return 'Hai kak, ';
  return '';
}

function countEmoji(text) {
  const matches = String(text || '').match(/[\u{1F300}-\u{1FAFF}✨😉😊]/gu);
  return matches ? matches.length : 0;
}

function trimExtraEmoji(text) {
  let seen = 0;
  return String(text || '').replace(/[\u{1F300}-\u{1FAFF}✨😉😊]/gu, match => {
    seen += 1;
    return seen <= 1 ? match : '';
  }).replace(/\s{2,}/g, ' ').trim();
}

const hasGreetingPrefix = !!ctx.hasGreetingPrefix ||
  /^(halo|hallo|hello|hi|hey|hai|hei|assalamualaikum|selamat pagi|selamat siang|selamat sore|selamat malam)/i.test(userText);

const cleanBase = rawReply || fallbackReply;
let isJoin = classifyJoinIntent(ctx.userMessage, cleanBase);

const explicitRegistration =
  /^(daftar|join|mau daftar|mau join|pengen daftar|pengen join|ingin daftar|ingin join)\b/i.test(userText) ||
  /(boleh|bisa)\s*(kirim|isi)\s*(form|formulir)/i.test(userText) ||
  /(saya|aku|sy|aq)\s*(mau|ingin|pengen)\s*(daftar|join|booking)\b/i.test(userText);

if (explicitRegistration) isJoin = true;

let cleanReply = humanClean(cleanBase).replace(/\s*\[INTENT:JOIN\]\s*/g, '').trim() || fallbackReply;

// Hard override for deterministic schedule
if (
  ['SCHEDULE_SPECIFIC_DAY', 'SCHEDULE_GENERAL'].includes(answerMode) &&
