}

if (answerMode === 'GREETING' && hasGreetingPrefix && cleanReply && !startsWithGreeting(cleanReply)) {
  const greeting = getGreeting(userText);
  if (greeting) {
    cleanReply = greeting + cleanReply.charAt(0).toLowerCase() + cleanReply.slice(1);
  }
}

if (!hasGreetingPrefix && answerMode !== 'GREETING') {
  cleanReply = cleanReply
    .replace(/^(selamat pagi|selamat siang|selamat sore|selamat malam|pagi kak|siang kak|sore kak|malam kak|hai kak|halo kak|hello kak|hi kak|hai|halo|hello|hi|assalamualaikum|waalaikumsalam)[!,.:\s-]*/i, '')
