  cleanReply = cleanReply.replace(/[\u{1F300}-\u{1FAFF}✨😉😊]/gu, '').trim();
} else if (countEmoji(cleanReply) > 1) {
  cleanReply = trimExtraEmoji(cleanReply);
}

cleanReply = cleanReply
  .replace(/\n{3,}/g, '\n\n')
  .replace(/[ \t]+\n/g, '\n')
  .trim() || fallbackReply;

const charLength = cleanReply.length;
let delaySeconds;
if (charLength < 80) delaySeconds = 3;
else if (charLength < 200) delaySeconds = 4;
else if (charLength < 400) delaySeconds = 5;
else delaySeconds = 6;

return {
