function hasHallucinationSignals(text, mode) {
  const t = String(text || '').toLowerCase();
  if (!t) return true;
  if (/\bzumba\b/i.test(t)) return true;
  if (/\b(database|prompt|assistant|language model|chatgpt|openai)\b/i.test(t)) return true;
  if (/\[alamat lengkap gym\]/i.test(t)) return true;
  if (mode !== 'LOCATION' && /\b(jl\.|jalan\s+[a-z]|rt\s*\/\s*rw|kelurahan|kecamatan|blok\s+[a-z])\b/i.test(t)) return true;
  return false;
}

function isTooDifferentFromParsed(baseText, styledText) {
  const base = cleanText(baseText).toLowerCase();
  const styled = cleanText(styledText).toLowerCase();

  if (!base || !styled) return false;

  const baseWords = base.split(/\s+/).filter(Boolean);
  const styledWords = styled.split(/\s+/).filter(Boolean);

  if (styledWords.length > baseWords.length * 2.2) return true;
  if (styledWords.length < Math.max(3, Math.floor(baseWords.length * 0.35))) return true;

  return false;
}

function extractCapitalizedNames(text) {
  const matches = String(text || '').match(/\b[A-Z][a-z]+(?:\s+[A-Z][a-z]+)?\b/g) || [];
  return [...new Set(matches)];
}

function hasInvalidCoachName(text, validCoachNames) {
  if (!validCoachNames.length) return false;

  const valid = validCoachNames.map(normalizeText).filter(Boolean);
  const candidates = extractCapitalizedNames(text);

  return candidates.some(name => {
    const normalized = normalizeText(name);
    if (!normalized) return false;
    return !valid.includes(normalized) && /\bcoach\b|\bpelatih\b|\btrainer\b|\binstruktur\b/i.test(String(text || ''));
  });
}

function buildCoachReply(rows) {
  if (!rows.length) {
    return 'Maaf ya kak 😊 Untuk kelas tersebut, informasi coach yang mengajar belum tersedia saat ini. Untuk informasi terbarunya, kakak bisa langsung menanyakan ke admin ya.';
  }

  if (rows.length === 1) {
    const row = rows[0];
    const lines = [`Untuk kelas itu, Kakak akan didampingi oleh Coach ${row.nama_coach} 😊`];
    if (row.specialist) lines.push(`Specialist: ${row.specialist}`);
    if (row.hari_mengajar) lines.push(`Hari mengajar: ${row.hari_mengajar}`);
    return lines.join('\n');
  }

  const lines = ['Untuk kelas tersebut, tersedia coach berikut ya kak:'];
  rows.forEach(row => {
    const detail = [
      row.nama_coach || '',
      row.specialist ? `(${row.specialist})` : ''
    ].filter(Boolean).join(' ');
    if (detail) lines.push(`- ${detail}`);
  });

  const hariLines = rows
    .map(row => row.nama_coach && row.hari_mengajar ? `- ${row.nama_coach}: ${row.hari_mengajar}` : '')
    .filter(Boolean);

  if (hariLines.length) {
    lines.push('');
    lines.push('Hari mengajar:');
    lines.push(...hariLines);
  }

  return lines.join('\n');
}

function countEmoji(text) {
  const matches = String(text || '').match(/[\u{1F300}-\u{1FAFF}✨😉😊]/gu);
  return matches ? matches.length : 0;
}

function trimExtraEmoji(text) {
  let seen = 0;
  return String(text || '').replace(/[\u{1F300}-\u{1FAFF}✨😉😊]/gu, match => {
    seen += 1;
    return seen <= 1 ? match : '';
  }).replace(/\s{2,}/g, ' ').trim();
}

let finalReply = cleanText(styledReplyRaw);
let replyStatus = 'styled_ok';
let usedFallback = false;
let fallbackReason = '';

if (!finalReply) {
  finalReply = parsedReply;
  replyStatus = 'fallback_to_parsed';
  usedFallback = true;
  fallbackReason = 'empty_stylist_output';
}

if (!usedFallback && hasDoubleGreeting(finalReply)) {
  finalReply = parsedReply;
  replyStatus = 'fallback_to_parsed';
  usedFallback = true;
  fallbackReason = 'double_greeting_detected';
}

if (!usedFallback && hasHallucinationSignals(finalReply, answerMode)) {
  finalReply = parsedReply;
  replyStatus = 'fallback_to_parsed';
  usedFallback = true;
  fallbackReason = 'hallucination_signal_detected';
}

if (!usedFallback && isTooDifferentFromParsed(parsedReply, finalReply)) {
  finalReply = parsedReply;
  replyStatus = 'fallback_to_parsed';
  usedFallback = true;
  fallbackReason = 'styled_reply_too_different';
}

if (!usedFallback && hasRobotCta(finalReply) && !hasRobotCta(parsedReply)) {
  finalReply = parsedReply;
  replyStatus = 'fallback_to_parsed';
  usedFallback = true;
  fallbackReason = 'robotic_cta_reintroduced';
}

if (!usedFallback && hasPromoTone(finalReply) && !hasPromoTone(parsedReply)) {
  finalReply = parsedReply;
  replyStatus = 'fallback_to_parsed';
  usedFallback = true;
  fallbackReason = 'promo_tone_reintroduced';
}

if (!usedFallback && answerMode === 'COACH_INFO') {
  if (hasInvalidCoachName(finalReply, matchedCoachNames)) {
    finalReply = buildCoachReply(matchedCoachRows);
    replyStatus = 'fallback_to_coach_guard';
    usedFallback = true;
    fallbackReason = 'invalid_coach_name_detected';
  }
}

if (!usedFallback && answerMode === 'COACH_INFO' && matchedCoachRows.length > 0) {
  const normalizedReply = normalizeText(finalReply);
  const hasKnownCoach = matchedCoachNames.some(name => normalizedReply.includes(normalizeText(name)));
  if (!hasKnownCoach) {
    finalReply = buildCoachReply(matchedCoachRows);
    replyStatus = 'fallback_to_coach_guard';
    usedFallback = true;
    fallbackReason = 'coach_name_missing_after_styling';
  }
}

finalReply = cleanText(finalReply);

if (answerMode === 'SOCIAL_MEDIA' || answerMode === 'WEIGHT_EXPECTATION') {
  finalReply = finalReply.replace(/[\u{1F300}-\u{1FAFF}✨😉😊]/gu, '').trim();
} else if (countEmoji(finalReply) > 1) {
  finalReply = trimExtraEmoji(finalReply);
}

finalReply = finalReply
  .replace(/\n{3,}/g, '\n\n')
  .replace(/[ \t]+\n/g, '\n')
  .trim();

return {
  json: {
    ...parsed,
    final_reply: finalReply,
    replyText: finalReply,
    reply_status: replyStatus,
    used_fallback: usedFallback,
    fallback_reason: fallbackReason,
    stylist_reply_raw: styledReplyRaw,
