).trim();

const userText = rawUserMessage.toLowerCase();

function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function titleCaseDay(day) {
  const map = {
    senin: 'Senin',
    selasa: 'Selasa',
    rabu: 'Rabu',
    kamis: 'Kamis',
    jumat: 'Jumat',
    sabtu: 'Sabtu',
    minggu: 'Minggu'
  };
  return map[day] || null;
}

function normalizeDayToken(day) {
  return normalizeText(day).replace(/^jum at$/i, 'jumat');
}

const nowJkt = new Date(
  new Date().toLocaleString('en-US', { timeZone: 'Asia/Jakarta' })
);

const dayNames = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
const currentDayName = dayNames[nowJkt.getDay()];
const currentDayNormalized = normalizeDayToken(currentDayName);

const resolvedUserText = userText
  .replace(/\bhari ini\b/g, currentDayNormalized)
  .replace(/\bsekarang\b(?=.*jadwal)/g, currentDayNormalized)
  .replace(/\bjum'at\b/g, 'jumat');

const dayRegex = /\bsenin\b|\bselasa\b|\brabu\b|\bkamis\b|\bjumat\b|\bjum'at\b|\bsabtu\b|\bminggu\b/gi;
const dayMatchesRaw = resolvedUserText.match(dayRegex) || [];
const uniqueDays = [...new Set(dayMatchesRaw.map(normalizeDayToken).filter(Boolean))];
const matchedDay = uniqueDays.length > 0 ? titleCaseDay(uniqueDays[0]) : null;

const hasScheduleKeyword =
  /\bjadwal\b|\bjam\b|\bkapan\b|\bhari\b|\bsetiap hari\b|\btiap hari\b|\bopen class\b/.test(userText);

const wantsFullSchedule =
  /\bjadwal lengkap\b|\bjadwal full\b|\bjadwal semua\b|\bsemua jadwal\b|\blist jadwal\b|\bdaftar jadwal\b|\bsemua kelas\b/.test(userText);

const asksClassExistenceByDay =
  /\bada\b.*\b(senin|selasa|rabu|kamis|jumat|jum'at|sabtu|minggu)\b|\b(senin|selasa|rabu|kamis|jumat|jum'at|sabtu|minggu)\b.*\bada\b/.test(userText);

const asksEveryDay =
  /\bsetiap hari\b|\btiap hari\b|\beveryday\b|\bevery day\b/.test(userText);

const matchedClassName = String(
  classDetail.matched_class_name ||
  classDetail.matched_class ||
  classDetail.class_detail_payload?.nama_olahraga ||
  ''
).trim();

const classFound = !!(
  (classDetail.class_matched || classDetail.class_detail_found) &&
  matchedClassName
);

const coachQuestion =
  /\bcoach\b|\bpelatih\b|\btrainer\b|\binstruktur\b|\bsiapa yang ngajar\b|\bsiapa coachnya\b/.test(userText);

const pureCoachQuestion = coachQuestion && !hasScheduleKeyword;

const classDetailQuestion =
  !!classDetail.class_detail_intent &&
  !hasScheduleKeyword &&
  !matchedDay &&
  !asksEveryDay &&
  !asksClassExistenceByDay;

let scheduleIntent = false;
let scheduleQueryType = 'none';

if (!pureCoachQuestion && !classDetailQuestion) {
  if (wantsFullSchedule) {
    scheduleIntent = true;
    scheduleQueryType = 'full_schedule';
  } else if (classFound && matchedDay) {
    scheduleIntent = true;
    scheduleQueryType = 'class_and_day';
  } else if (classFound && (hasScheduleKeyword || asksEveryDay || asksClassExistenceByDay)) {
    scheduleIntent = true;
    scheduleQueryType = 'class_only';
  } else if (!classFound && matchedDay && hasScheduleKeyword) {
    scheduleIntent = true;
    scheduleQueryType = 'day_only';
  } else if (!classFound && matchedDay && /\bkelas\b|\bclass\b/.test(userText)) {
    scheduleIntent = true;
    scheduleQueryType = 'day_only';
  } else if (!classFound && hasScheduleKeyword) {
    scheduleIntent = true;
    scheduleQueryType = 'general_schedule';
