  $('Resolve Schedule Query').first().json ||
  item;

function safeGet(nodeName) {
  try {
    return $(nodeName).all().map(d => d.json).filter(Boolean);
  } catch (e) {
    return [];
  }
}

function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeDay(value) {
  const v = normalizeText(value).replace(/^jum at$/i, 'jumat');
  const map = {
    senin: 'Senin',
    selasa: 'Selasa',
    rabu: 'Rabu',
    kamis: 'Kamis',
    jumat: 'Jumat',
    sabtu: 'Sabtu',
    minggu: 'Minggu'
  };
  return map[v] || null;
}

function daySortValue(day) {
  const order = {
    senin: 1,
    selasa: 2,
    rabu: 3,
    kamis: 4,
    jumat: 5,
    sabtu: 6,
    minggu: 7
  };
  return order[normalizeText(day)] || 99;
}

function parseTimeForSort(value) {
  const text = String(value || '').trim();
  const match = text.match(/(\d{1,2})[.:](\d{2})/);
  if (!match) return 9999;
  const hh = Number(match[1]);
  const mm = Number(match[2]);
  if (!Number.isFinite(hh) || !Number.isFinite(mm)) return 9999;
  return (hh * 60) + mm;
}

function isActive(row) {
  const s = String(row.status || row.Status || '').toLowerCase().trim();
  return !s || s === 'aktif' || s === 'active';
}

function pickClassField(row) {
  return String(row.kelas || row.nama_kelas || '').trim();
}

function sortScheduleRows(rows) {
  return [...rows].sort((a, b) => {
    const dayDiff = daySortValue(a.hari) - daySortValue(b.hari);
    if (dayDiff !== 0) return dayDiff;

    const timeDiff = parseTimeForSort(a.jam) - parseTimeForSort(b.jam);
    if (timeDiff !== 0) return timeDiff;

    return pickClassField(a).localeCompare(pickClassField(b));
  });
}

function formatRow(row) {
  const parts = [];
  if (row.hari) parts.push(row.hari);
  if (row.jam) parts.push(`jam ${row.jam}`);
  if (pickClassField(row)) parts.push(pickClassField(row));
  if (row.coach) parts.push(`dengan coach ${row.coach}`);
  return parts.join(' ');
}

function formatScheduleByClass(className, rows) {
  if (!rows.length) {
    return `Maaf kak, aku belum bisa memastikan jadwal kelas ${className} 😊 Mau aku berikan nomor adminnya biar kakak bisa tanya langsung?`;
  }

  const lines = rows.map(row => `- ${row.hari}, ${row.jam}${row.coach ? ` dengan coach ${row.coach}` : ''}`);
  return [
    `Jadwal kelas ${className} adalah sebagai berikut:`,
    '',
    ...lines
  ].join('\n');
}

function formatScheduleByClassAndDay(className, dayName, rows) {
  if (!rows.length) {
    return `Untuk kelas ${className}, saat ini tidak ada jadwal di hari ${dayName} ya kak.`;
  }

  const lines = rows.map(row => `- ${row.jam}${row.coach ? ` dengan coach ${row.coach}` : ''}`);
  return [
    `Untuk kelas ${className} di hari ${dayName}, jadwalnya adalah:`,
    '',
    ...lines
  ].join('\n');
}

function formatScheduleByDay(dayName, rows) {
  if (!rows.length) {
    return `Maaf kak, aku belum bisa memastikan jadwal untuk hari ${dayName} 😊 Mau aku berikan nomor adminnya biar kakak bisa tanya langsung?`;
  }

  const lines = rows.map(row => {
    const className = pickClassField(row) || 'Kelas';
    return `- ${row.jam} - ${className}${row.coach ? ` (${row.coach})` : ''}`;
  });

  return [
    `Jadwal kelas di hari ${dayName} adalah sebagai berikut:`,
    '',
    ...lines
  ].join('\n');
}

function formatFullSchedule(rows) {
  if (!rows.length) {
    return 'Maaf kak, aku belum bisa membantu mengecek jadwalnya saat ini 😊 Mau aku berikan nomor adminnya biar kakak bisa tanya langsung?';
  }

  const lines = rows.map(row => {
    const className = pickClassField(row) || 'Kelas';
    return `- ${row.hari}, ${row.jam} - ${className}${row.coach ? ` (${row.coach})` : ''}`;
  });

  return [
    'Berikut jadwal kelas yang tersedia saat ini:',
    '',
    ...lines
  ].join('\n');
}

function formatGeneralSchedule(rows) {
  if (!rows.length) {
    return 'Maaf kak, aku belum bisa membantu mengecek jadwalnya saat ini 😊 Mau aku berikan nomor adminnya biar kakak bisa tanya langsung?';
  }

  const preview = rows.slice(0, 12).map(row => {
    const className = pickClassField(row) || 'Kelas';
    return `- ${row.hari}, ${row.jam} - ${className}${row.coach ? ` (${row.coach})` : ''}`;
  });

  const text = [
    'Berikut jadwal yang tersedia saat ini:',
    '',
    ...preview
  ];

  if (rows.length > preview.length) {
    text.push('');
    text.push('Kalau kakak mau, aku bisa bantu cek jadwal untuk kelas atau hari tertentu juga ya.');
  }

  return text.join('\n');
}

const allJadwal = safeGet('Fetch Sheet Jadwal')
  .filter(row => row && pickClassField(row))
  .filter(isActive)
  .map(row => ({
    ...row,
    kelas: pickClassField(row),
    hari: normalizeDay(row.hari) || String(row.hari || '').trim(),
    jam: String(row.jam || '').trim(),
    coach: String(row.coach || '').trim()
  }));

const scheduleIntent = !!scheduleQuery.schedule_intent;
const queryType = String(scheduleQuery.schedule_query_type || 'none');
const matchedClass = String(scheduleQuery.matched_schedule_class || '').trim();
const matchedDay = String(scheduleQuery.matched_schedule_day || '').trim();

const normalizedMatchedClass = normalizeText(matchedClass);
const normalizedMatchedDay = normalizeText(matchedDay);

let filteredRows = [];
let scheduleFound = false;
let scheduleAnswerText = '';
let scheduleNoMatchReason = '';
let scheduleAnswerType = queryType;

if (!scheduleIntent) {
  return {
    json: {
      ...item,
      schedule_answer_ready: false,
      schedule_found: false,
      schedule_result_rows: [],
      schedule_result_count: 0,
      schedule_answer_text: '',
      schedule_answer_type: 'none',
      schedule_no_match_reason: 'schedule_intent_false',
      schedule_debug_build: {
        total_rows: allJadwal.length,
        query_type: queryType,
        matched_class: matchedClass || null,
        matched_day: matchedDay || null
      }
    }
  };
}

if (queryType === 'class_and_day') {
  filteredRows = allJadwal.filter(row =>
    normalizeText(row.kelas) === normalizedMatchedClass &&
    normalizeText(row.hari) === normalizedMatchedDay
  );
  filteredRows = sortScheduleRows(filteredRows);
  scheduleFound = filteredRows.length > 0;
  scheduleAnswerText = formatScheduleByClassAndDay(matchedClass, matchedDay, filteredRows);
  if (!scheduleFound) scheduleNoMatchReason = 'class_and_day_not_found';
} else if (queryType === 'class_only') {
  filteredRows = allJadwal.filter(row =>
    normalizeText(row.kelas) === normalizedMatchedClass
  );
  filteredRows = sortScheduleRows(filteredRows);
  scheduleFound = filteredRows.length > 0;
  scheduleAnswerText = formatScheduleByClass(matchedClass, filteredRows);
  if (!scheduleFound) scheduleNoMatchReason = 'class_not_found';
} else if (queryType === 'day_only') {
  filteredRows = allJadwal.filter(row =>
    normalizeText(row.hari) === normalizedMatchedDay
  );
  filteredRows = sortScheduleRows(filteredRows);
  scheduleFound = filteredRows.length > 0;
  scheduleAnswerText = formatScheduleByDay(matchedDay, filteredRows);
  if (!scheduleFound) scheduleNoMatchReason = 'day_not_found';
} else if (queryType === 'full_schedule') {
  filteredRows = sortScheduleRows(allJadwal);
  scheduleFound = filteredRows.length > 0;
  scheduleAnswerText = formatFullSchedule(filteredRows);
  if (!scheduleFound) scheduleNoMatchReason = 'full_schedule_empty';
} else if (queryType === 'general_schedule') {
  filteredRows = sortScheduleRows(allJadwal);
  scheduleFound = filteredRows.length > 0;
  scheduleAnswerText = formatGeneralSchedule(filteredRows);
  if (!scheduleFound) scheduleNoMatchReason = 'general_schedule_empty';
} else {
  filteredRows = [];
  scheduleFound = false;
  scheduleAnswerText = '';
  scheduleNoMatchReason = 'unsupported_schedule_query_type';
}

return {
  json: {
    ...item,
    schedule_answer_ready: true,
    schedule_found: scheduleFound,
    schedule_result_rows: filteredRows.map(row => ({
      hari: row.hari || '',
      jam: row.jam || '',
      kelas: row.kelas || '',
      coach: row.coach || ''
    })),
    schedule_result_count: filteredRows.length,
    schedule_answer_text: scheduleAnswerText,
    schedule_answer_type: scheduleAnswerType,
    schedule_no_match_reason: scheduleNoMatchReason,
    schedule_debug_build: {
      total_rows: allJadwal.length,
      query_type: queryType,
      matched_class: matchedClass || null,
      matched_day: matchedDay || null,
      result_count: filteredRows.length,
      first_result: filteredRows[0]
        ? {
            hari: filteredRows[0].hari || '',
            jam: filteredRows[0].jam || '',
            kelas: filteredRows[0].kelas || '',
            coach: filteredRows[0].coach || ''
          }
        : null
    }
  }
};

const item = $input.first().json || {};

const refData = $('Collect Reference Data (Sequential)').first().json || {};
const incoming = $('Normalize Incoming Message').first().json || {};

const rawUserMessage = String(
  incoming.userMessage ||
  refData.userMessage ||
  ''
).trim();

const userText = rawUserMessage.toLowerCase();
const answerMode = String(refData.answerMode || 'GENERAL');

function safeGet(nodeName) {
  try {
    return $(nodeName).all().map(d => d.json).filter(Boolean);
  } catch (e) {
    return [];
  }
}

function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function isActive(row) {
  const s = String(row.status || row.Status || '').toLowerCase().trim();
  return !s || s === 'aktif' || s === 'active';
}

function rupiahNumber(value) {
  const numeric = Number(String(value || '').replace(/\D/g, ''));
  return Number.isFinite(numeric) && numeric > 0 ? numeric : null;
}

function rupiahFormat(value) {
  const n = rupiahNumber(value);
  return n ? `Rp${n.toLocaleString('id-ID')}` : String(value || '-').trim() || '-';
}

function normalizeRupiahMentions(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/(\d+)\s*jt\b/g, (_, n) => String(Number(n) * 1000000))
    .replace(/(\d+)\s*juta\b/g, (_, n) => String(Number(n) * 1000000))
    .replace(/(\d+)\s*rb\b/g, (_, n) => String(Number(n) * 1000))
    .replace(/(\d+)\s*ribu\b/g, (_, n) => String(Number(n) * 1000))
    .replace(/(\d+)\s*k\b/g, (_, n) => String(Number(n) * 1000));
}

function extractMentionedPrices(text) {
  const normalized = normalizeRupiahMentions(text);
  return [...new Set(
    (normalized.match(/\d{4,9}/g) || [])
      .map(v => Number(v))
      .filter(v => Number.isFinite(v) && v > 0)
  )];
}

function packageTokens(name) {
  return String(name || '')
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter(token =>
      token.length >= 4 &&
      !['days', 'challenge', 'program', 'paket', 'class', 'hari', 'fit'].includes(token)
    );
}

function scoreHargaRow(row, msg, mentionedPrices) {
  const fullName = String(row.nama_paket || '').toLowerCase();
  if (!fullName) return 0;

  let score = 0;

  if (msg.includes(fullName)) score += 100;

  const rowPrice = rupiahNumber(row.harga);
  if (rowPrice && mentionedPrices.includes(rowPrice)) score += 80;

  const tokens = packageTokens(fullName);
  const matchedTokens = tokens.filter(token => msg.includes(token));
  score += matchedTokens.length * 10;

  if (tokens.length > 0 && matchedTokens.length === tokens.length) {
    score += 25;
  }

  if (/challenge/.test(msg) && /challenge/.test(fullName)) score += 8;
  if (/private/.test(msg) && /private/.test(fullName)) score += 8;
  if (/vip/.test(msg) && /vip/.test(fullName)) score += 8;
  if (/reguler/.test(msg) && /reguler/.test(fullName)) score += 8;

  return score;
}

function filterMonthlyRows(rows) {
  return rows.filter(row => /\bbulan\b/i.test(String(row.durasi || '')));
}

function formatPackageList(rows) {
  const lines = rows.map(row => {
    const nama = String(row.nama_paket || '').trim();
    const harga = rupiahFormat(row.harga);
    const durasi = String(row.durasi || '-').trim();
    return `- ${nama}: ${harga} (${durasi})`;
  });

  return [
    'Berikut harga paket yang tersedia saat ini:',
    '',
    ...lines,
    '',
    'Setiap paket memiliki fasilitas dan ketentuan yang berbeda ya kak.',
    'Kalau kakak mau, saya bisa jelaskan detail dari paket yang kakak pilih.'
  ].join('\n');
}

function formatMonthlyPackageList(rows) {
  const lines = rows.map(row => {
    const nama = String(row.nama_paket || '').trim();
    const harga = rupiahFormat(row.harga);
    const durasi = String(row.durasi || '-').trim();
    return `- ${nama}: ${harga} (${durasi})`;
  });

  return [
    'Untuk harga per bulan di StepUp, berikut pilihannya ya kak:',
    '',
    ...lines,
    '',
    'Setiap paket memiliki fasilitas dan ketentuan yang berbeda ya kak.',
    'Kalau kakak mau, saya bisa jelaskan detail dari paket yang kakak pilih.'
  ].join('\n');
}

function formatPackageDetail(row) {
  const lines = [];
  const nama = String(row.nama_paket || '').trim();
  const harga = rupiahFormat(row.harga);
  const durasi = String(row.durasi || '-').trim();

  lines.push(`${nama} (${harga}, ${durasi})`);

  if (row.fasilitas_utama) {
    lines.push('');
    lines.push('Fasilitas:');
    String(row.fasilitas_utama)
      .split(/[,;]/)
      .map(v => v.trim())
      .filter(Boolean)
      .forEach(v => lines.push(`- ${v}`));
  }

  if (row.ketentuan) {
    lines.push('');
    lines.push(`Ketentuan: ${String(row.ketentuan).trim()}`);
  }

  if (row.cocok_untuk) {
    lines.push('');
    lines.push(`Cocok untuk: ${String(row.cocok_untuk).trim()}`);
  }

  return lines.join('\n');
}

function formatPackageComparison(rows) {
  const chosen = rows.slice(0, 2);
  return chosen.map(row => formatPackageDetail(row)).join('\n\n');
}

const allHarga = safeGet('Fetch Sheet Harga')
  .filter(row => row && row.nama_paket)
  .filter(isActive);

const asksPrice =
  /harga|biaya|berapa|paket|member|membership|promo|diskon|trial|free|pricelist|price list|list harga|tarif|cicil|worth|sepadan|sebanding/.test(userText) ||
  /(\d+\s*(k|rb|ribu|jt|juta)\b|\b\d{4,9}\b)/.test(userText);

const asksComparison =
  /apa bedanya|bedanya apa|beda apa|beda nya|perbedaannya|perbedaan|compare|bandingkan|vs\b|versus/i.test(userText);

const asksDetail =
  /fasilitas|ketentuan|include|termasuk|dapat apa|dapet apa|apa aja/i.test(userText);

const asksMonthlyPrice =
  /\bper\s*bln\b|\bper\s*bulan\b|\bbulanan\b|\b1\s*bulan\b|\b2\s*bulan\b|\b3\s*bulan\b|\bbulan\b/.test(userText);

const mentionedPrices = extractMentionedPrices(userText);

const matchedHargaRows = allHarga
  .map(row => ({ row, score: scoreHargaRow(row, userText, mentionedPrices) }))
  .filter(entry => entry.score > 0)
  .sort((a, b) => b.score - a.score || (rupiahNumber(a.row.harga) || 0) - (rupiahNumber(b.row.harga) || 0))
  .map(entry => entry.row);

let priceIntent = false;
let priceAnswerType = 'none';
let priceRows = [];
let priceAnswerText = '';
let priceFound = false;
let priceNoMatchReason = '';

if (
  ['PRICE_GENERAL_CLARIFY', 'PRICE_SPECIFIC', 'PRICE_OBJECTION', 'CLASS_AND_PRICE'].includes(answerMode) ||
  asksPrice
) {
  priceIntent = true;

  if (asksComparison && matchedHargaRows.length >= 2) {
    priceAnswerType = 'comparison';
    priceRows = matchedHargaRows.slice(0, 2);
    priceAnswerText = formatPackageComparison(priceRows);
    priceFound = priceRows.length > 0;
  } else if (asksDetail && matchedHargaRows.length >= 1) {
    priceAnswerType = 'detail';
    priceRows = [matchedHargaRows[0]];
    priceAnswerText = formatPackageDetail(priceRows[0]);
    priceFound = priceRows.length > 0;
  } else if (asksMonthlyPrice) {
    priceAnswerType = 'monthly';
    priceRows = filterMonthlyRows(allHarga);
    priceAnswerText = formatMonthlyPackageList(priceRows);
    priceFound = priceRows.length > 0;
  } else if (matchedHargaRows.length >= 1 && answerMode !== 'PRICE_GENERAL_CLARIFY') {
    priceAnswerType = 'specific';
    priceRows = matchedHargaRows;
    priceAnswerText = formatPackageList(priceRows);
    priceFound = priceRows.length > 0;
  } else {
    priceAnswerType = 'general';
    priceRows = allHarga;
    priceAnswerText = formatPackageList(priceRows);
    priceFound = priceRows.length > 0;
  }

  if (!priceFound) {
    priceNoMatchReason = 'price_data_not_found';
    priceAnswerText = 'Mohon maaf kak, data harga belum ditemukan saat ini ya.';
  }
}

return {
  json: {
    ...item,
    price_answer_ready: priceIntent,
    price_found: priceFound,
    price_answer_type: priceAnswerType,
    price_result_rows: priceRows.map(row => ({
      nama_paket: String(row.nama_paket || '').trim(),
      kategori: String(row.kategori || '').trim(),
      harga: String(row.harga || '').trim(),
      durasi: String(row.durasi || '').trim(),
      fasilitas_utama: String(row.fasilitas_utama || '').trim(),
      ketentuan: String(row.ketentuan || '').trim(),
      cocok_untuk: String(row.cocok_untuk || '').trim()
    })),
    price_answer_text: priceAnswerText,
    price_no_match_reason: priceNoMatchReason,
    price_debug: {
      answer_mode: answerMode,
      asks_price: asksPrice,
      asks_monthly_price: asksMonthlyPrice,
      matched_rows: matchedHargaRows.length,
      chosen_rows: priceRows.length,
      answer_type: priceAnswerType
    }
  }
};
